CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_weight_increment integer := 1;
    v_phase integer;
    v_player_birthday_marker text;
    v_team_short_marker text;
    v_player_removal_cutoff integer;
    v_team_removal_cutoff integer;
BEGIN
    FOR v_phase IN 1..9 LOOP
        CASE v_phase
            WHEN 1 THEN
                v_player_birthday_marker := 'phase_1';
                v_team_short_marker := 'log_phase_1';
                v_player_removal_cutoff := arg3;
            WHEN 2 THEN
                v_player_birthday_marker := 'phase_2';
                v_team_short_marker := 'log_phase_2';
                v_player_removal_cutoff := arg3 + 1;
            WHEN 3 THEN
                v_player_birthday_marker := 'phase_3';
                v_team_short_marker := 'log_phase_3';
                v_player_removal_cutoff := arg3 + 10;
            WHEN 4 THEN
                v_player_birthday_marker := 'phase_4';
                v_team_short_marker := 'log_phase_4';
                v_player_removal_cutoff := arg3 + 3;
            WHEN 5 THEN
                v_player_birthday_marker := 'phase_5';
                v_team_short_marker := 'log_phase_5';
                v_player_removal_cutoff := arg3 + 4;
            WHEN 6 THEN
                v_player_birthday_marker := 'phase_6';
                v_team_short_marker := 'log_phase_6';
                v_player_removal_cutoff := arg3 + 5;
            WHEN 7 THEN
                v_player_birthday_marker := 'phase_7';
                v_team_short_marker := 'log_phase_7';
                v_player_removal_cutoff := arg3 + 6;
            WHEN 8 THEN
                v_player_birthday_marker := 'phase_8';
                v_team_short_marker := 'log_phase_8';
                v_player_removal_cutoff := arg3 + 7;
            WHEN 9 THEN
                v_player_birthday_marker := 'phase_9';
                v_team_short_marker := 'log_phase_9';
                v_player_removal_cutoff := arg3 + 8;
        END CASE;

        v_team_removal_cutoff := arg6 + (v_phase - 1);

        UPDATE "Player"
           SET "birthday" = v_player_birthday_marker;

        DELETE FROM "Player"
         WHERE "player_api_id" < v_player_removal_cutoff;

        UPDATE "Team"
           SET "team_short_name" = v_team_short_marker;

        DELETE FROM "Team"
         WHERE "team_fifa_api_id" < v_team_removal_cutoff;
    END LOOP;

    UPDATE "Player"
       SET "weight" = "weight" + v_weight_increment
     WHERE "height" < arg1;

    IF arg5 IS NOT NULL THEN
        UPDATE "Team"
           SET "team_long_name" = arg5
         WHERE "team_short_name" = 'log_phase_9'
           AND "team_api_id" >= arg4;
    END IF;

    UPDATE "Player_Attributes"
       SET "potential" = "overall_rating"
     WHERE "player_api_id" >= arg3
       AND "potential" < "overall_rating";

    UPDATE "Team_Attributes" AS ta
       SET "defenceAggression" = ta."defencePressure"
     WHERE ta."defenceAggression" < ta."defencePressure"
       AND EXISTS (
           SELECT 1
             FROM "Team" AS t
            WHERE t."team_api_id" = ta."team_api_id"
              AND t."team_fifa_api_id" >= (arg6 + 8)
       );
END;
$$;

